var PARTS = [
    { key: "cu", name: "Control Unit (CU)", short: "CU", color: "#7c5cff", stage: 1, cost: 120, cps: 2, slot: [2, 0, 3, 1], desc: "The director of the processor.", levels: ["Hardwired control", "Microcoded control", "Pipelined control paths", "Out-of-order control", "Speculative control"], levelNotes: ["Fixed combinational logic sequences one instruction at a time.", "ROM micro-instructions support richer multi-step instructions.", "Propagates control signals stage-by-stage alongside the pipeline.", "Schedules ready instructions dynamically to reduce stalls.", "Predicts branch paths early and commits results in order."], what: "Reads each instruction and sends signals telling the other parts what to do and when.", analogy: "Like a conductor in an orchestra. It plays no instrument, but nothing happens in the right order without it." },
    { key: "alu", name: "Arithmetic Logic Unit (ALU)", short: "ALU", color: "#ff6b6b", stage: 1, cost: 180, cps: 3, slot: [2, 1, 3, 2], desc: "Performs arithmetic and logical operations.", levels: ["4-bit ALU", "8-bit ALU", "16-bit ALU + flags", "32-bit ALU (RV32I)", "64-bit ALU (RV64I)"], levelNotes: ["4-bit ripple-carry datapath (early Intel 4004 class).", "8-bit integer width with basic carry/zero flags.", "16-bit datapath with full status flags (N, Z, C, V).", "32-bit standard RISC-V / MIPS integer word width.", "64-bit integer datapath for large memory addressing."], what: "Does the math (add, subtract) and the logic (AND, OR, compare) on binary numbers.", analogy: "Like the calculator on your desk. You give it two numbers and an operation, and it hands back the answer." },
    { key: "regs", name: "Registers", short: "REG", color: "#3aa0ff", stage: 1, cost: 260, cps: 4, slot: [0, 1, 2, 2], desc: "Tiny, ultra-fast storage inside the CPU.", levels: ["4 registers", "8 registers", "16 general registers", "32 RISC registers", "Register renaming"], levelNotes: ["Minimal accumulator + scratch registers inside the core.", "8 named working registers reduce frequent RAM spills.", "16 architectural registers hold loop counters and pointers.", "32-register file (classic MIPS/RISC-V size) cuts memory traffic.", "Maps architectural names to extra physical slots to remove WAR/WAW hazards."], what: "A handful of named storage slots that hold the numbers the CPU is using right now.", analogy: "Like sticky notes on your monitor. Instantly in view, unlike the filing cabinet (RAM) across the room." },
    { key: "clock", name: "Clock", short: "CLK", color: "#ffb020", stage: 2, cost: 150, cps: 3, slot: [0, 0, 2, 1], desc: "Sets the beat that keeps every part in step.", levels: ["5 MHz clock", "33 MHz clock", "200 MHz clock", "1.5 GHz clock", "4.5 GHz boost clock"], levelNotes: ["Early microprocessor era (~200 ns cycle period).", "32-bit workstation era (30 ns period).", "Pipelined shorter stages allow 5 ns clock period.", "Gigahertz deep-pipeline silicon (0.67 ns period).", "High-frequency boost within thermal & critical-path limits."], what: "Sends a steady pulse. On each tick every part takes one step, bounded by the critical path.", analogy: "Like the drummer in a rowing boat. Everyone pulls their oar on the beat." },
    { key: "pipe", name: "Pipeline", short: "PIPE", color: "#ff8a3d", stage: 2, cost: 600, cps: 8, slot: [0, 3, 8, 1], desc: "Overlaps instructions so no part sits idle.", levels: ["2-stage (Fetch/Exec)", "5-stage (IF-ID-EX-MEM-WB)", "2-way Superscalar", "3-way Superscalar", "4-way Wide Issue"], levelNotes: ["Overlaps fetch and execute for ~0.50 ideal IPC.", "Classic textbook 5-stage RISC pipeline: 1.00 ideal IPC.", "Dual execution pipes issue up to 2 instructions/cycle (2.00 IPC).", "Three parallel issue lanes push ideal IPC to 3.00.", "Wide superscalar backend targets up to 4.00 ideal IPC."], what: "Splits each instruction into stages so several instructions are in progress at the same time.", analogy: "Like doing laundry. While load 1 is in the dryer, load 2 is already in the washer." },
    { key: "decoder", name: "Instruction Decoder", short: "DEC", color: "#14b8a6", stage: 3, cost: 900, cps: 10, slot: [5, 0, 3, 1], desc: "Turns instruction bits into control signals.", levels: ["Fixed 6-bit decode", "Richer opcode decode", "32-bit fixed ISA", "Micro-op translator", "4-wide decode"], levelNotes: ["Parses simple 2-bit opcode and 2-bit register fields.", "Handles immediate constants and branch offsets.", "Fixed-length 32-bit RISC decoding in a single cycle.", "Breaks complex instructions into simple internal micro-ops.", "Decodes up to 4 instructions simultaneously each cycle."], what: "Takes the binary instruction and works out which operation and which registers it means.", analogy: "Like a translator who turns a sentence in machine language into steps the other parts can follow." },
    { key: "l1", name: "L1 Cache", short: "L1", color: "#22c55e", stage: 4, cost: 1500, cps: 16, slot: [0, 4, 4, 2], desc: "Smallest, fastest memory next to the core.", levels: ["1 KB L1", "4 KB L1", "16 KB Split I/D", "32 KB 8-way L1", "64 KB Low-latency"], levelNotes: ["Tiny 1 KB SRAM buffer catches tight inner loops.", "4 KB SRAM cuts DRAM trips significantly.", "Splits Instruction & Data caches (Harvard style) to avoid structural hazards!", "8-way set associative 32 KB reduces conflict misses.", "64 KB high-speed L1 keeps hot working sets ~1 ns away."], what: "Keeps recently used data right beside the CPU so it does not wait for slow RAM.", analogy: "Like keeping your textbook open on your desk instead of walking to the library every time." },
    { key: "l2", name: "L2 Cache", short: "L2", color: "#84cc16", stage: 4, cost: 2800, cps: 26, slot: [0, 6, 8, 2], desc: "Bigger, slightly slower backup cache.", levels: ["16 KB L2", "64 KB L2", "256 KB L2", "1 MB L2", "4 MB L2"], levelNotes: ["Catches L1 capacity misses before reaching main DRAM.", "64 KB unified L2 holds both instructions and data.", "256 KB per-core L2 cuts average memory access time (AMAT).", "1 MB L2 holds large textures and working arrays on-die.", "4 MB shared L2 keeps multi-core data close."], what: "A larger cache that catches what L1 misses, reducing trips all the way to RAM.", analogy: "Like the bookshelf in your room. Bigger than your desk, still much closer than the library." },
    { key: "fpu", name: "Floating-Point Unit (FPU)", short: "FPU", color: "#ec4899", stage: 5, cost: 5000, cps: 40, slot: [5, 1, 3, 2], desc: "Fast math on decimal numbers.", levels: ["IEEE-754 Single (32b)", "IEEE-754 Double (64b)", "Pipelined FPU", "FMA (Fused Mul-Add)", "SIMD Vector FPU"], levelNotes: ["Hardware sign/exponent/mantissa logic for 32-bit floats.", "64-bit double precision reduces scientific rounding error.", "Pipelined FP add/mul stages sustain 1 op per cycle.", "Fused Multiply-Add performs a×b+c in one rounding step.", "Vector lanes process multiple floats in parallel per instruction."], what: "Handles numbers with decimal points (like 3.14159) in IEEE-754 sign + exponent + mantissa format.", analogy: "Like a scientific calculator with a decimal key, versus one that only handles integers." },
    { key: "cores", name: "Multi-core", short: "CORES", color: "#06b6d4", stage: 5, cost: 9000, cps: 70, slot: [4, 4, 4, 2], desc: "More cores means more parallel work.", levels: ["1 Core (Single)", "2 Cores (Dual)", "4 Cores (Quad)", "8 Cores (Octa)", "16 Cores (SoC)"], levelNotes: ["Single hardware thread executes one stream at a time.", "Dual cores double throughput on independent tasks.", "Quad cores balance parallel work against Amdahl's serial fraction.", "8 cores accelerate parallel rendering & batch jobs.", "16-core SoC scales massively parallel workloads."], what: "Several complete CPU cores on one chip running independent instructions at the same time.", analogy: "Like opening more checkout lanes at a store. Serial tasks still wait in one line." }
];
